   206	}
   207	
   208	export interface IntelPlayerState {
   209	  readonly id: string;
   210	  /** The held types as of the last processed tick, in type order; losses and completions are diffs of these. */
   211	  readonly held: readonly RubbingType[];
   212	  readonly journal: readonly JournalRumor[];
   213	  /** Whether the player's final-island route is active (they hold a full set) and whether they ever had one. */
   214	  readonly routeActive: boolean;
   215	  readonly routeEver: boolean;
   216	  /** The boundary of the snapshot current when the player last got a carrier sighting, or -1. */
   217	  readonly lastSightingBoundary: number;
   218	  /** The deferred sighting message, or null. */
   219	  readonly pending: PendingSighting | null;
   220	}
   221	
   222	/** One carried copy at a snapshot. The holder is kept only so a player is never shown their own copy. */
   223	export interface CarrierSnapshotEntry {
   224	  readonly sector: number;
   225	  readonly type: RubbingType;
   226	  readonly holder: string;
   227	}
   228	
   229	export interface CarrierSnapshot {
   230	  /** k for the boundary `controlStartTick + k × carrierIntervalTicks`. */
   231	  readonly boundary: number;
   232	  /** The tick whose world view it records (the boundary tick unless ticks were skipped). */
   233	  readonly tick: number;
   234	  readonly entries: readonly CarrierSnapshotEntry[];
   235	}
   236	
   237	/** The information state: plain integer data that `hashState` covers entirely. */
   238	export interface IntelState {
   239	  /** The last world tick processed. */
   240	  readonly tick: number;
   241	  readonly rng: number;
   242	  /** Whether control start has been processed. */
   243	  readonly started: boolean;
   244	  /** Players seen in the last view, by id. */
   245	  readonly players: readonly IntelPlayerState[];
   246	  /** The latest two snapshots, older first. */
   247	  readonly snapshots: readonly CarrierSnapshot[];
   248	  readonly finalSectorAnnounced: boolean;
   249	  readonly sectorRevealed: boolean;
   250	  /** The index j of the last carrier broadcast (`carrierRevealTick + j × carrierIntervalTicks`), or -1. */
   251	  readonly lastCarrierBroadcast: number;
   252	  /** Every targeted request id answered so far, sorted. */
   253	  readonly requestIds: readonly string[];
   254	}
   255	
   256	/** A state before any tick. `tick` must come before control start, so control start is always crossed. */
   257	export function createIntelState(config: IntelConfig, seed: number, tick = -1): IntelState {
   258	  requireInteger(seed, "seed");
   259	  requireInteger(tick, "tick");
   260	  if (tick >= config.controlStartTick) throw new RangeError(`the intel state must start before control start (tick ${config.controlStartTick})`);
   261	  return {
   262	    tick,
   263	    rng: seed >>> 0,
   264	    started: false,
   265	    players: [],
   266	    snapshots: [],
   267	    finalSectorAnnounced: false,
   268	    sectorRevealed: false,
   269	    lastCarrierBroadcast: -1,
   270	    requestIds: [],
   271	  };
   272	}
   273	
   274	// ---------------------------------------------------------------------------------------------------------------------
   275	// Messages: every one names its recipients. Bodies never carry a player id, a rubbing id or an exact position, except
   276	// the final island's point in a `final-route` to a player holding a full set.
   277	
   278	export type IntelRecipients =
   279	  | { readonly kind: "player"; readonly playerId: string }
   280	  | { readonly kind: "players"; readonly playerIds: readonly string[] }
   281	  | { readonly kind: "everyone" };
   282	
   283	export interface SectorRef {
   284	  readonly sector: number;
   285	  readonly name: string;
   286	}
   287	
   288	export type IntelRumorTarget =
   289	  | { readonly kind: "island"; readonly island: number; readonly name: string }
   290	  | { readonly kind: "sector"; readonly sector: number; readonly name: string };
   291	
   292	/** One type of a carrier-sighting message, with the trigger that asked for it. */
   293	export interface CarrierSighting {
   294	  readonly type: RubbingType;
   295	  readonly reason: IntelLeadReason;
   296	  readonly sector: number;
   297	  readonly name: string;
   298	}
   299	
   300	export type IntelMessageBody =
   301	  /** A journal lead toward a missing type. */
   302	  | { readonly kind: "rumor"; readonly tick: number; readonly entry: number; readonly type: RubbingType; readonly reason: IntelLeadReason; readonly target: IntelRumorTarget }
   303	  /** One-shot: per type, the sector where a carrier of it was at `seenTick` (the previous snapshot). Never tracked. */
   304	  | { readonly kind: "carrier-sighting"; readonly tick: number; readonly seenTick: number; readonly sightings: readonly CarrierSighting[] }
   305	  /** A free trigger found nothing to point at. */
   306	  | { readonly kind: "no-lead"; readonly tick: number; readonly type: RubbingType; readonly reason: IntelLeadReason }
   307	  | { readonly kind: "rumor-stale"; readonly tick: number; readonly entry: number; readonly type: RubbingType }
   308	  | { readonly kind: "rumor-resolved"; readonly tick: number; readonly entry: number; readonly type: RubbingType }
   309	  /** A first full set exists: the final island's broad sector (§5). */
   310	  | { readonly kind: "final-sector"; readonly tick: number; readonly sector: number; readonly name: string }
   311	  /** The exact route, to a full-set holder only; `restored` after a lost set is whole again. */
   312	  | { readonly kind: "final-route"; readonly tick: number; readonly x: number; readonly y: number; readonly restored: boolean }
   313	  | { readonly kind: "final-route-inactive"; readonly tick: number }
   314	  /** Minute 20: sectors holding sealed sources and recovery caches. */
   315	  | { readonly kind: "sector-reveal"; readonly tick: number; readonly sources: readonly SectorRef[]; readonly caches: readonly SectorRef[] }
   316	  /** Minute 28 on: the carriers' sectors and types at the latest snapshot. */
   317	  | { readonly kind: "carrier-report"; readonly tick: number; readonly seenTick: number; readonly carriers: readonly (SectorRef & { readonly type: RubbingType })[] };
   318	
   319	export type IntelMessageKind = IntelMessageBody["kind"];
   320	
   321	export interface IntelMessage {
   322	  readonly to: IntelRecipients;
   323	  readonly body: IntelMessageBody;
   324	}
   325	
   326	export interface IntelStepResult {
   327	  readonly state: IntelState;
   328	  readonly messages: readonly IntelMessage[];
   329	  /** One per request, in the order given. */
   330	  readonly outcomes: readonly TargetedRumorOutcome[];
   331	}

