22	const T = 256;
23	const tile = (x: number, y: number): IntelPoint => ({ x: x * T + 128, y: y * T + 128 });
24	/** A 30 × 30 test sea: sector bands are tiles 0–9, 10–19 and 20–29. Islands sit in the four corner sectors. */
25	const MAP = {
26	  widthTiles: 30,
27	  heightTiles: 30,
28	  subUnitsPerTile: T,
29	  islands: [{ name: "Palm Key" }, { name: "Ash Isle" }, { name: "Mist Rock" }, { name: "Old Ruin" }],
30	};
31	const ISLAND_AT = [tile(4, 4), tile(25, 4), tile(4, 25), tile(25, 25)];
32	const ISLAND_SECTOR = [0, 2, 6, 8];
33	/** A point in each of the nine sectors. */
34	const S = [tile(2, 2), tile(15, 2), tile(27, 2), tile(2, 15), tile(15, 15), tile(27, 15), tile(2, 27), tile(15, 27), tile(27, 27)] as const;
35	const FINAL = { x: 15 * T + 7, y: 16 * T + 3 };
36	const START = 100;
37	
38	/** Real reveal times and a 100-tick (5 s) carrier interval, so carrier scenarios stay short. */
39	const quick = createIntelConfig({
40	  preset: "slice",
41	  finalIsland: FINAL,
42	  controlStartTick: START,
43	  map: MAP,
44	  rules: { ...intelRules, carrierIntervalTicks: 100, sightingDelayTicks: 100, sectorRevealTicks: 1_000, carrierRevealTicks: 2_000 },
45	});
46	const real = createIntelConfig({ preset: "slice", finalIsland: FINAL, controlStartTick: START, map: MAP });
47	/** The quick timings with the alpha's four types (sun, moon, tide, storm), so several types can wait at once. */
48	const quickAlpha = createIntelConfig({
49	  preset: "alpha",
50	  finalIsland: FINAL,
51	  controlStartTick: START,
52	  map: MAP,
53	  rules: { ...intelRules, carrierIntervalTicks: 100, sightingDelayTicks: 100, sectorRevealTicks: 1_000, carrierRevealTicks: 2_000 },
54	});
55	
56	const typeOf = (id: string) => id.slice(0, id.indexOf("-")) as RubbingType;
57	const source = (id: string, island: number): IntelRubbing => ({ id, type: typeOf(id), place: { kind: "source", island, ...ISLAND_AT[island]! } });
58	const cached = (id: string, at: IntelPoint): IntelRubbing => ({ id, type: typeOf(id), place: { kind: "cache", ...at } });
59	const carried = (id: string, playerId: string): IntelRubbing => ({ id, type: typeOf(id), place: { kind: "carried", playerId } });
60	const reserved = (id: string, playerId: string): IntelRubbing => ({ id, type: typeOf(id), place: { kind: "duel", playerId } });
61	
62	interface World {
63	  readonly players: Readonly<Record<string, IntelPoint>>;
64	  readonly rubbings: readonly IntelRubbing[];
65	}
66	
67	/** Recursively frozen, so a step that mutated its input would throw. */
68	function deepFreeze<T>(value: T): T {
69	  if (typeof value === "object" && value !== null && !Object.isFrozen(value)) {
70	    Object.freeze(value);
71	    for (const child of Object.values(value)) deepFreeze(child);
72	  }
73	  return value;
74	}
75	
76	function viewOf(tick: number, world: World): IntelWorldView {
77	  return { tick, players: Object.entries(world.players).map(([id, at]) => ({ id, ...at })), rubbings: world.rubbings };
78	}
79	
80	/** Steps with frozen input and state, checking neither changes. */
81	class Run {
82	  state: IntelState;
83	  constructor(
84	    readonly config: IntelConfig,
85	    seed = 1,
86	  ) {
87	    this.state = createIntelState(config, seed);
88	  }
89	
90	  step(tick: number, world: World, requests: TargetedRumorRequest[] = []): IntelStepResult {
91	    const view = deepFreeze(viewOf(tick, world));
92	    const before = hashState(deepFreeze(this.state));
93	    const stepped = stepIntel(this.config, this.state, view, deepFreeze(requests));
94	    expect(hashState(this.state)).toBe(before);
95	    this.state = stepped.state;
96	    return stepped;
97	  }
98	
99	  available(tick: number, world: World, playerId: string, type: RubbingType) {
100	    return targetedRumorAvailability(this.config, this.state, viewOf(tick, world), playerId, type);
101	  }
102	}
103	
104	function to(result: IntelStepResult, playerId: string): IntelMessageBody[] {
105	  return result.messages.filter((message) => message.to.kind === "player" && message.to.playerId === playerId).map((message) => message.body);
106	}
107	
108	function everyone(result: IntelStepResult): IntelMessageBody[] {
109	  return result.messages.filter((message) => message.to.kind === "everyone").map((message) => message.body);
110	}
111	
112	function only<K extends IntelMessageBody["kind"]>(bodies: IntelMessageBody[], kind: K): Extract<IntelMessageBody, { kind: K }> {
113	  const found = bodies.filter((body) => body.kind === kind);
114	  expect(found).toHaveLength(1);
115	  return found[0] as Extract<IntelMessageBody, { kind: K }>;
116	}
117	
118	const request = (requestId: string, playerId: string, type: RubbingType): TargetedRumorRequest => ({ requestId, playerId, type });
119	
120	describe("control start and starting rumors (§2)", () => {
121	  it("say nothing before control start, then give each player a rumor toward a type they lack", () => {
122	    const run = new Run(quick);
123	    const world: World = {
124	      players: { A: S[4], B: S[0], C: S[8] },
125	      rubbings: [carried("sun-1", "A"), carried("moon-1", "A"), source("sun-2", 0), source("moon-2", 1), carried("moon-3", "C")],
126	    };
127	    for (const tick of [0, 50, START - 1]) {
128	      const stepped = run.step(tick, world, [request(`early-${tick}`, "B", "sun")]);
129	      expect(stepped.messages).toEqual([]);
130	      expect(stepped.outcomes).toEqual([{ requestId: `early-${tick}`, result: "none" }]);
131	      expect(run.state.started).toBe(false);
132	    }
133	    const start = run.step(START, world);
134	    expect(run.state.started).toBe(true);
135	    // A already holds a full set: the final sector and route instead of a rumor.
136	    expect(to(start, "A").map((body) => body.kind)).toEqual(["final-route"]);
137	    expect(everyone(start)).toEqual([{ kind: "final-sector", tick: START, sector: 4, name: "Central Waters" }]);
138	    // B lacks both: a rumor for either type, pointing at the island holding it.
139	    const b = only(to(start, "B"), "rumor");
140	    expect(b).toMatchObject({ entry: 1, reason: "start" });
141	    expect(b.target).toEqual(b.type === "sun" ? { kind: "island", island: 0, name: "Palm Key" } : { kind: "island", island: 1, name: "Ash Isle" });
142	    // C holds moon: sun only.
143	    expect(only(to(start, "C"), "rumor")).toEqual({ kind: "rumor", tick: START, entry: 1, type: "sun", reason: "start", target: { kind: "island", island: 0, name: "Palm Key" } });
144	    // A player first seen after control start gets a starting rumor then.
145	    const late = run.step(START + 30, { ...world, players: { ...world.players, D: S[2] } });
146	    expect(only(to(late, "D"), "rumor")).toMatchObject({ reason: "start", tick: START + 30 });
147	    expect(to(late, "B")).toEqual([]);
148	  });
149	
150	  it("point a start only at a source or a cache, never at a carrier, also for a late joiner", () => {
151	    const run = new Run(quick);
152	    // Every moon is carried by A; sun is sealed on Palm Key.
153	    const world = (players: Record<string, IntelPoint>): World => ({ players, rubbings: [carried("sun-1", "A"), carried("moon-1", "A"), source("sun-2", 0)] });
154	    run.step(START, world({ A: S[4] }));
155	    // B joins lacking both: the starting rumor goes to sun, the type with a source, not to the carried moon.
156	    const late = run.step(START + 30, world({ A: S[4], B: S[2] }));
157	    expect(to(late, "B")).toEqual([
158	      { kind: "rumor", tick: START + 30, entry: 1, type: "sun", reason: "start", target: { kind: "island", island: 0, name: "Palm Key" } },
159	    ]);
160	    // C joins holding sun (the last sealed one, collected), lacking moon, every copy of which is carried: no starting
161	    // rumor, a no-lead, and no sighting then or at any later boundary.
162	    const collected: World = { players: { A: S[4], B: S[2], C: S[6] }, rubbings: [carried("sun-1", "A"), carried("moon-1", "A"), carried("sun-2", "C")] };
163	    const carriedOnly = run.step(START + 40, collected);
164	    expect(to(carriedOnly, "C")).toEqual([{ kind: "no-lead", tick: START + 40, type: "moon", reason: "start" }]);
165	    for (const tick of [START + 100, START + 200, START + 300]) {
166	      expect(to(run.step(tick, collected), "C")).toEqual([]);
167	      expect(run.state.players.find((player) => player.id === "C")!.pending).toBeNull();
168	    }
169	  });
170	
171	  it("give the same rumor for the same seed, and a seed decides between equal targets", () => {
172	    const world: World = { players: { A: S[4] }, rubbings: [source("sun-1", 0), source("sun-2", 1), source("moon-1", 2), source("moon-2", 3)] };
173	    const targetFor = (seed: number) => {
174	      const stepped = new Run(quick, seed).step(START, world);
175	      return only(to(stepped, "A"), "rumor");
