183	describe("rumor targets (§3, §11)", () => {
184	  it("prefer a sealed source, then a cache, then a carrier sighting", () => {
185	    const players = { A: S[4], B: S[2] };
186	    const world: World = { players, rubbings: [carried("sun-1", "A"), source("moon-1", 3), cached("moon-2", S[1]), carried("moon-3", "B")] };
187	    let run = new Run(quick);
