191	    const cache = run.step(START + 10, world, [request("r1", "A", "moon")]);
192	    expect(cache.outcomes).toEqual([{ requestId: "r1", result: "rumor" }]);
193	    expect(only(to(cache, "A"), "rumor").target).toEqual({ kind: "sector", sector: 1, name: "Northern Waters" });
194	    // …and no carrier sighting while some copy is not carried.
