214	  it("pick a sealed source over a cache for every seed, on start, targeted and fresh rumors", () => {
215	    const islands = new Set<number>();
216	    for (let seed = 0; seed < 24; seed++) {
217	      const run = new Run(quick, seed);
218	      // A lacks moon; moon is sealed on two islands and cached in two sectors, so both kinds are eligible.
219	      const moons = [source("moon-1", 1), source("moon-2", 3), cached("moon-3", S[1]), cached("moon-4", S[7])];
220	      const world: World = { players: { A: S[4], B: S[0] }, rubbings: [carried("sun-1", "A"), ...moons] };
221	      const start = only(to(run.step(START, world), "A"), "rumor");
222	      expect(start.target.kind).toBe("island");
