230	
231	      // A free fresh rumor after a theft, with a source and a cache of the lost type both eligible.
232	      const fresh = new Run(quick, seed);
233	      const players = { A: S[4], B: S[2] };
234	      const rest = [source("sun-2", 0), cached("sun-3", S[5]), source("moon-2", 1)];
235	      fresh.step(START, { players, rubbings: [carried("sun-1", "A"), carried("moon-1", "A"), ...rest] });
236	      const theft = fresh.step(START + 10, { players, rubbings: [carried("sun-1", "B"), carried("moon-1", "A"), ...rest] });
237	      expect(only(to(theft, "A"), "rumor")).toMatchObject({ type: "sun", reason: "fresh", target: { kind: "island", island: 0 } });
238	    }
239	    // The seed chooses among the sources, never a cache.
240	    expect([...islands].sort()).toEqual([1, 3]);
241	  });
242	
243	  it("never give a rumor for a held type, nor point a player at their own former copy", () => {
244	    for (let seed = 0; seed < 12; seed++) {
245	      const run = new Run(quick, seed);
246	      const players = { A: S[0], B: S[4], C: S[8] };
247	      // Only two moons: A's and C's. B then steals A's.
248	      const before: World = { players, rubbings: [carried("sun-1", "B"), carried("sun-2", "A"), carried("moon-1", "A"), carried("moon-2", "C")] };
249	      run.step(START, before);
250	      const held = run.step(START + 10, before, [
251	        request("held", "A", "moon"),
252	      ]);
253	      expect(held.outcomes).toEqual([{ requestId: "held", result: "none" }]);
254	      expect(to(held, "A")).toEqual([]);
255	      const stolen: World = { players: { ...players, B: S[2] }, rubbings: [carried("sun-1", "B"), carried("sun-2", "A"), carried("moon-1", "B"), carried("moon-2", "C")] };
256	      // The fresh rumor finds every moon carried and no previous snapshot yet: it waits for the next boundary.
257	      expect(to(run.step(START + 50, stolen), "A")).toEqual([{ kind: "final-route-inactive", tick: START + 50 }]);
258	      const delivered = run.step(START + 100, stolen);
259	      // The previous snapshot (tick 100) has A's own moon in the north-west and C's in the south-east: never A's own.
260	      expect(only(to(delivered, "A"), "carrier-sighting")).toMatchObject({ seenTick: START, sightings: [{ type: "moon", reason: "fresh", sector: 8 }] });
261	    }
262	  });
263	});
264	
265	describe("losses (§11)", () => {
266	  it("give a free fresh rumor when a type is stolen, and nothing when a rubbing is only reserved in a duel", () => {
267	    const run = new Run(quick);
268	    const players = { A: S[4], B: S[5] };
269	    const others = [source("sun-2", 0), source("moon-1", 1)];
270	    const start = run.step(START, { players, rubbings: [carried("sun-1", "A"), ...others] });
271	    expect(only(to(start, "B"), "rumor")).toBeDefined();
272	    const duel = run.step(START + 5, { players, rubbings: [reserved("sun-1", "A"), ...others] });
273	    expect(duel.messages).toEqual([]);
274	    const theft = run.step(START + 6, { players, rubbings: [carried("sun-1", "B"), ...others] });
275	    expect(only(to(theft, "A"), "rumor")).toEqual({
276	      kind: "rumor",
277	      tick: START + 6,
278	      entry: 2,
279	      type: "sun",
280	      reason: "fresh",
281	      target: { kind: "island", island: 0, name: "Palm Key" },
282	    });
283	  });
