95	const DIRECTIONS = [
96	  [1, 0],
97	  [1, 1],
98	  [0, 1],
99	  [-1, 1],
100	  [-1, 0],
101	  [-1, -1],
102	  [0, -1],
103	  [1, -1],
104	] as const;
