196	        if (stolen !== undefined) rubbings.set(stolen.id, { ...stolen, place: { kind: "carried", playerId: winner } });
197	      }
198	      for (const rubbing of rubbings.values()) {
199	        const place = rubbing.place;
200	        if (place.kind === "carried" && inDuel(place.playerId)) rubbings.set(rubbing.id, { ...rubbing, place: { kind: "duel", playerId: place.playerId } });
201	      }
202	    }
203	    if (chance(12)) {
204	      const a = pick(free);
205	      const b = pick(free.filter((id) => id !== a));
206	      if (a !== undefined && b !== undefined) {
207	        duels.push({ a, b, until: tick + 20 + draw(80) });
208	        for (const rubbing of rubbings.values()) {
209	          const place = rubbing.place;
210	          if (place.kind === "carried" && (place.playerId === a || place.playerId === b)) {
