212	          }
213	        }
214	      }
215	    }
216	    // Leaving drops everything into a cache where the ship was; someone new may join.
217	    if (chance(2) && players.size > 2) {
218	      const id = pick(free);
219	      if (id !== undefined) {
220	        const player = players.get(id)!;
221	        for (const rubbing of rubbings.values()) {
222	          if (rubbing.place.kind === "carried" && rubbing.place.playerId === id) rubbings.set(rubbing.id, { ...rubbing, place: { kind: "cache", x: player.x, y: player.y } });
223	        }
224	        players.delete(id);
225	      }
226	    }
227	    if (chance(2) && players.size < preset.maxPlayers) join();
228	
229	    const requests: TargetedRumorRequest[] = [];
230	    if (tick > config.controlStartTick - 20 && chance(15)) {
231	      const playerId = pick([...players.keys(), "nobody"])!;
232	      const reuse = requestIds.length > 0 && chance(250);
233	      const requestId = reuse ? requestIds[draw(requestIds.length)]! : `req-${requestIds.length}`;
234	      if (!reuse) requestIds.push(requestId);
235	      requests.push({ requestId, playerId, type: config.types[draw(config.types.length)]! });
236	    }
237	    const view: IntelWorldView = {
238	      tick,
239	      players: [...players].map(([id, player]) => ({ id, x: player.x, y: player.y })),
240	      rubbings: [...rubbings.values()],
241	    };
242	    script.push(deepFreeze({ view, requests }));
243	  }
244	  return script;
245	}
